<template><section data-ui-id="weekly-panel" class="quadrant weekly-panel"><div class="panel-heading"><span class="eyebrow">最近 7 天 · 7×24</span><span class="legend">低　高</span></div><Heatmap7d :days="heatmap?.days" :peak="heatmap?.peakTokens"/></section><section data-ui-id="trend-panel" class="quadrant trend-panel"><div class="panel-heading"><span class="eyebrow">最近 30 天</span><strong>{{format(trend?.totalTokens)}}</strong></div><Calendar30d :days="trend?.days"/><div class="trend-summary"><span>峰值 {{format(trend?.peakTokens)}}</span><span>日均 {{format(trend?.averageTokens)}}</span><span>价值 {{trend?.valueLabel||'—'}}</span></div></section></template><script setup>import Heatmap7d from './Heatmap7d.vue';import Calendar30d from './Calendar30d.vue';defineProps({heatmap:Object,trend:Object});const format=v=>v==null?'—':new Intl.NumberFormat('zh-CN').format(v)</script>
